FROM jsonb_to_recordset($g2story$[{"lessonId":"47ae629d-9ce9-4d18-89ab-1d25bc0a2874","lessonTitle":"الدرس الأول: فرحة القرقاعون","page":6,"activity_order":205,"activity_type":"multiple_choice","title":"أفهم تفاصيل الحكاية","section":"practice","prompt":"مع من استعد الأطفال للاحتفال بالقرقاعون؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"في ليلة القرقاعون، استعد الأطفال للاحتفال مع أسرهم. لبسوا ملابس جميلة، وتبادلوا التهاني، ثم نظموا ما جمعوه في أكياس صغيرة. قالت مريم: الفرحة أجمل حين نتشاركها باحترام ولا نؤذي أحدًا. وافقها أخوها، وشكر الجيران على استقبالهم اللطيف.","options":["مع عمال المصنع","مع أسرهم","مع رجال الإطفاء"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"remember"},"answer":{"correct":"مع أسرهم"}},{"lessonId":"47ae629d-9ce9-4d18-89ab-1d25bc0a2874","lessonTitle":"الدرس الأول: فرحة القرقاعون","page":6,"activity_order":206,"activity_type":"multiple_choice","title":"أتذكر المعلومة المناسبة","section":"practice","prompt":"ماذا فعل الأطفال بعد تبادل التهاني؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"في ليلة القرقاعون، استعد الأطفال للاحتفال مع أسرهم. لبسوا ملابس جميلة، وتبادلوا التهاني، ثم نظموا ما جمعوه في أكياس صغيرة. قالت مريم: الفرحة أجمل حين نتشاركها باحترام ولا نؤذي أحدًا. وافقها أخوها، وشكر الجيران على استقبالهم اللطيف.","options":["تركوا الاحتفال","نظموا ما جمعوه في أكياس صغيرة","رموا الأكياس في الطريق"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"understand"},"answer":{"correct":"نظموا ما جمعوه في أكياس صغيرة"}},{"lessonId":"47ae629d-9ce9-4d18-89ab-1d25bc0a2874","lessonTitle":"الدرس الأول: فرحة القرقاعون","page":6,"activity_order":207,"activity_type":"multiple_choice","title":"أفسر القيمة أو النتيجة","section":"practice","prompt":"كيف عبَّرت مريم عن الفرح المسؤول؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"في ليلة القرقاعون، استعد الأطفال للاحتفال مع أسرهم. لبسوا ملابس جميلة، وتبادلوا التهاني، ثم نظموا ما جمعوه في أكياس صغيرة. قالت مريم: الفرحة أجمل حين نتشاركها باحترام ولا نؤذي أحدًا. وافقها أخوها، وشكر الجيران على استقبالهم اللطيف.","options":["نحتفل وحدنا","نتشارك الفرح باحترام دون إيذاء أحد","نزعج الجيران لنفرح"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"apply"},"answer":{"correct":"نتشارك الفرح باحترام دون إيذاء أحد"}},{"lessonId":"38594fae-4bf7-41c3-aa76-52590a1dbdda","lessonTitle":"الدرس التاسع: الرجل الطائر","page":9,"activity_order":205,"activity_type":"multiple_choice","title":"أفهم تفاصيل الحكاية","section":"practice","prompt":"بماذا حلم فهد عندما شاهد الطيور؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"تخيل فهد أن بوسعه الطيران مثل الطيور. رسم جناحين كبيرين وفكر في شكل آلة تستطيع التحليق. أخبرته معلمته أن الاختراع يحتاج إلى تجربة ودراسة لقواعد السلامة. كتب فهد في دفتره: أحلم بفكرة جديدة، وأتعلم أولًا كيف أختبرها بطريقة آمنة.","options":["بتربية الأسماك","بالطيران مثلها","بالعيش في البحر"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"remember"},"answer":{"correct":"بالطيران مثلها"}},{"lessonId":"38594fae-4bf7-41c3-aa76-52590a1dbdda","lessonTitle":"الدرس التاسع: الرجل الطائر","page":9,"activity_order":206,"activity_type":"multiple_choice","title":"أتذكر المعلومة المناسبة","section":"practice","prompt":"ماذا رسم فهد عندما تخيل اختراعه؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"تخيل فهد أن بوسعه الطيران مثل الطيور. رسم جناحين كبيرين وفكر في شكل آلة تستطيع التحليق. أخبرته معلمته أن الاختراع يحتاج إلى تجربة ودراسة لقواعد السلامة. كتب فهد في دفتره: أحلم بفكرة جديدة، وأتعلم أولًا كيف أختبرها بطريقة آمنة.","options":["خريطة للمدينة","جناحين كبيرين","سفينة خشبية"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"understand"},"answer":{"correct":"جناحين كبيرين"}},{"lessonId":"38594fae-4bf7-41c3-aa76-52590a1dbdda","lessonTitle":"الدرس التاسع: الرجل الطائر","page":9,"activity_order":207,"activity_type":"multiple_choice","title":"أفسر القيمة أو النتيجة","section":"practice","prompt":"ما النصيحة التي قدمتها المعلمة لفهد؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"تخيل فهد أن بوسعه الطيران مثل الطيور. رسم جناحين كبيرين وفكر في شكل آلة تستطيع التحليق. أخبرته معلمته أن الاختراع يحتاج إلى تجربة ودراسة لقواعد السلامة. كتب فهد في دفتره: أحلم بفكرة جديدة، وأتعلم أولًا كيف أختبرها بطريقة آمنة.","options":["ترك الدراسة من أجل الطيران","تجربة الفكرة ودراسة قواعد السلامة","تجربة أي آلة دون إشراف"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"apply"},"answer":{"correct":"تجربة الفكرة ودراسة قواعد السلامة"}},{"lessonId":"f56f7e48-3753-4b5f-a26b-e5df6c416d67","lessonTitle":"الدرس الثالث: ما أجمل صناعة أجدادنا!","page":7,"activity_order":205,"activity_type":"multiple_choice","title":"أفهم تفاصيل الحكاية","section":"practice","prompt":"أين شاهد راشد أدوات الحرف القديمة؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"زار راشد معرضًا للحرف القديمة برفقة أسرته. رأى سلالًا منسوجة، وأدوات مصنوعة يدويًا، وتعرف إلى قيمة الصبر والدقة في العمل. سأله والده: لماذا نحافظ على هذه المهن؟ فقال: لأنها تخبرنا كيف عاش الناس، وتعلمنا تقدير جهودهم.","options":["في محطة للحافلات","في معرض للحرف القديمة","في ملعب لكرة القدم"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"remember"},"answer":{"correct":"في معرض للحرف القديمة"}},{"lessonId":"f56f7e48-3753-4b5f-a26b-e5df6c416d67","lessonTitle":"الدرس الثالث: ما أجمل صناعة أجدادنا!","page":7,"activity_order":206,"activity_type":"multiple_choice","title":"أتذكر المعلومة المناسبة","section":"practice","prompt":"أيُّ منتج شاهده راشد في المعرض؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"زار راشد معرضًا للحرف القديمة برفقة أسرته. رأى سلالًا منسوجة، وأدوات مصنوعة يدويًا، وتعرف إلى قيمة الصبر والدقة في العمل. سأله والده: لماذا نحافظ على هذه المهن؟ فقال: لأنها تخبرنا كيف عاش الناس، وتعلمنا تقدير جهودهم.","options":["أجهزة حاسوب","سلالًا منسوجة","سيارات حديثة"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"understand"},"answer":{"correct":"سلالًا منسوجة"}},{"lessonId":"f56f7e48-3753-4b5f-a26b-e5df6c416d67","lessonTitle":"الدرس الثالث: ما أجمل صناعة أجدادنا!","page":7,"activity_order":207,"activity_type":"multiple_choice","title":"أفسر القيمة أو النتيجة","section":"practice","prompt":"لماذا من المهم المحافظة على الحرف القديمة بحسب راشد؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"زار راشد معرضًا للحرف القديمة برفقة أسرته. رأى سلالًا منسوجة، وأدوات مصنوعة يدويًا، وتعرف إلى قيمة الصبر والدقة في العمل. سأله والده: لماذا نحافظ على هذه المهن؟ فقال: لأنها تخبرنا كيف عاش الناس، وتعلمنا تقدير جهودهم.","options":["لأنها بلا فائدة","لأنها تعرفنا حياة الناس وتعلمنا تقدير عملهم","لأنها تمنع العمل الحديث"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"apply"},"answer":{"correct":"لأنها تعرفنا حياة الناس وتعلمنا تقدير عملهم"}},{"lessonId":"a18a07b1-5cf1-48e5-b22d-edac1cf553d1","lessonTitle":"الدرس الثامن: شجرة الحياة","page":8,"activity_order":205,"activity_type":"multiple_choice","title":"أفهم تفاصيل الحكاية","section":"practice","prompt":"ما الذي أثار فضول يوسف؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"قرأ يوسف عنوان «شجرة الحياة» فشعر بالفضول. طلب من معلمته أن يعرف كيف تستطيع بعض الأشجار التكيف مع ظروف صعبة. اقترحت المعلمة البحث في مصادر موثوقة وملاحظة شكل الشجرة دون الإضرار بها. كتب يوسف سؤالًا للبحث ورسم شجرة كبيرة مع جذورها وأغصانها.","options":["طائرة ورقية","عنوان شجرة الحياة","مباراة رياضية"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"remember"},"answer":{"correct":"عنوان شجرة الحياة"}},{"lessonId":"a18a07b1-5cf1-48e5-b22d-edac1cf553d1","lessonTitle":"الدرس الثامن: شجرة الحياة","page":8,"activity_order":206,"activity_type":"multiple_choice","title":"أتذكر المعلومة المناسبة","section":"practice","prompt":"عن أي أمر أراد يوسف أن يسأل؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"قرأ يوسف عنوان «شجرة الحياة» فشعر بالفضول. طلب من معلمته أن يعرف كيف تستطيع بعض الأشجار التكيف مع ظروف صعبة. اقترحت المعلمة البحث في مصادر موثوقة وملاحظة شكل الشجرة دون الإضرار بها. كتب يوسف سؤالًا للبحث ورسم شجرة كبيرة مع جذورها وأغصانها.","options":["طريقة طبخ الأرز","قدرة بعض الأشجار على التكيف مع الظروف الصعبة","أسماء جميع السيارات"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"understand"},"answer":{"correct":"قدرة بعض الأشجار على التكيف مع الظروف الصعبة"}},{"lessonId":"a18a07b1-5cf1-48e5-b22d-edac1cf553d1","lessonTitle":"الدرس الثامن: شجرة الحياة","page":8,"activity_order":207,"activity_type":"multiple_choice","title":"أفسر القيمة أو النتيجة","section":"practice","prompt":"ما أسلوب التعلم الذي شجعته عليه المعلمة؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"قرأ يوسف عنوان «شجرة الحياة» فشعر بالفضول. طلب من معلمته أن يعرف كيف تستطيع بعض الأشجار التكيف مع ظروف صعبة. اقترحت المعلمة البحث في مصادر موثوقة وملاحظة شكل الشجرة دون الإضرار بها. كتب يوسف سؤالًا للبحث ورسم شجرة كبيرة مع جذورها وأغصانها.","options":["الاكتفاء بالتخمين دون بحث","البحث في مصادر موثوقة والملاحظة دون إضرار","كسر الأغصان لمعرفة العمر"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"apply"},"answer":{"correct":"البحث في مصادر موثوقة والملاحظة دون إضرار"}},{"lessonId":"f7ea6d0c-9381-4db6-987b-9b3a71ec1572","lessonTitle":"الدرس الثاني عشر: اختراع ينير الطريق","page":10,"activity_order":205,"activity_type":"multiple_choice","title":"أفهم تفاصيل الحكاية","section":"practice","prompt":"ماذا أراد سامي أن يصنع؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"فكر سامي في مصباح صغير يعمل في الأماكن المظلمة. رسم نموذجًا له وناقش مع والده كيف نحافظ على السلامة عند استخدام الكهرباء. اقترح الأب تجربة مصباح جاهز يعمل ببطارية آمنة وتحت إشراف شخص بالغ. تعلم سامي أن الاختراعات النافعة تجمع بين الفكرة الجيدة والحذر.","options":["شجرة اصطناعية","مصباحًا صغيرًا للأماكن المظلمة","لعبة مائية"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"remember"},"answer":{"correct":"مصباحًا صغيرًا للأماكن المظلمة"}},{"lessonId":"f7ea6d0c-9381-4db6-987b-9b3a71ec1572","lessonTitle":"الدرس الثاني عشر: اختراع ينير الطريق","page":10,"activity_order":206,"activity_type":"multiple_choice","title":"أتذكر المعلومة المناسبة","section":"practice","prompt":"ما التجربة التي اقترحها الأب؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"فكر سامي في مصباح صغير يعمل في الأماكن المظلمة. رسم نموذجًا له وناقش مع والده كيف نحافظ على السلامة عند استخدام الكهرباء. اقترح الأب تجربة مصباح جاهز يعمل ببطارية آمنة وتحت إشراف شخص بالغ. تعلم سامي أن الاختراعات النافعة تجمع بين الفكرة الجيدة والحذر.","options":["تجربة الكهرباء دون حذر","مصباح جاهز ببطارية آمنة وتحت إشراف بالغ","توصيل الأسلاك المكشوفة"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"understand"},"answer":{"correct":"مصباح جاهز ببطارية آمنة وتحت إشراف بالغ"}},{"lessonId":"f7ea6d0c-9381-4db6-987b-9b3a71ec1572","lessonTitle":"الدرس الثاني عشر: اختراع ينير الطريق","page":10,"activity_order":207,"activity_type":"multiple_choice","title":"أفسر القيمة أو النتيجة","section":"practice","prompt":"ما الدرس المستفاد من تجربة سامي؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"فكر سامي في مصباح صغير يعمل في الأماكن المظلمة. رسم نموذجًا له وناقش مع والده كيف نحافظ على السلامة عند استخدام الكهرباء. اقترح الأب تجربة مصباح جاهز يعمل ببطارية آمنة وتحت إشراف شخص بالغ. تعلم سامي أن الاختراعات النافعة تجمع بين الفكرة الجيدة والحذر.","options":["تجاهل نصائح الكبار","الاختراع النافع يجمع الفكرة والحذر","الاختراع لا يحتاج سلامة"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"apply"},"answer":{"correct":"الاختراع النافع يجمع الفكرة والحذر"}},{"lessonId":"8feb7c6a-3a80-4aa2-8f2d-24ff8792878c","lessonTitle":"الدرس الثاني: وطني الغالي","page":6,"activity_order":205,"activity_type":"multiple_choice","title":"أفهم تفاصيل الحكاية","section":"practice","prompt":"ماذا رفعت نورة في النشاط المدرسي؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"رفعت نورة علم البحرين في نشاط مدرسي. قالت لزملائها إن حب الوطن يظهر في المحافظة على الأماكن العامة، والجد في التعلم، ومساعدة الناس. اتفق الأطفال على تنظيف زاوية القراءة في المدرسة. وعند نهاية اليوم شعرت نورة بالفخر لأن الجميع شارك في عمل مفيد.","options":["خريطة قارة","علم البحرين","راية فريق رياضي"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"remember"},"answer":{"correct":"علم البحرين"}},{"lessonId":"8feb7c6a-3a80-4aa2-8f2d-24ff8792878c","lessonTitle":"الدرس الثاني: وطني الغالي","page":6,"activity_order":206,"activity_type":"multiple_choice","title":"أتذكر المعلومة المناسبة","section":"practice","prompt":"ما العمل الذي اتفق الأطفال على تنفيذه؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"رفعت نورة علم البحرين في نشاط مدرسي. قالت لزملائها إن حب الوطن يظهر في المحافظة على الأماكن العامة، والجد في التعلم، ومساعدة الناس. اتفق الأطفال على تنظيف زاوية القراءة في المدرسة. وعند نهاية اليوم شعرت نورة بالفخر لأن الجميع شارك في عمل مفيد.","options":["إتلاف الكتب","تنظيف زاوية القراءة","إغلاق المكتبة"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"understand"},"answer":{"correct":"تنظيف زاوية القراءة"}},{"lessonId":"8feb7c6a-3a80-4aa2-8f2d-24ff8792878c","lessonTitle":"الدرس الثاني: وطني الغالي","page":6,"activity_order":207,"activity_type":"multiple_choice","title":"أفسر القيمة أو النتيجة","section":"practice","prompt":"كيف يظهر حب الوطن بحسب ما ذكرته نورة؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"رفعت نورة علم البحرين في نشاط مدرسي. قالت لزملائها إن حب الوطن يظهر في المحافظة على الأماكن العامة، والجد في التعلم، ومساعدة الناس. اتفق الأطفال على تنظيف زاوية القراءة في المدرسة. وعند نهاية اليوم شعرت نورة بالفخر لأن الجميع شارك في عمل مفيد.","options":["الابتعاد عن أي عمل جماعي","المحافظة على المرافق والتعلم ومساعدة الآخرين","رمي النفايات في الساحة"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"apply"},"answer":{"correct":"المحافظة على المرافق والتعلم ومساعدة الآخرين"}},{"lessonId":"854e3f92-2bbe-47c9-b790-abde711524c3","lessonTitle":"الدرس الحادي عشر: المطعم الذكي","page":10,"activity_order":205,"activity_type":"multiple_choice","title":"أفهم تفاصيل الحكاية","section":"practice","prompt":"كيف عُرضت قائمة الطعام في المطعم؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"دخلت ليلى مطعمًا يستخدم شاشة لعرض قائمة الطعام. اختارت وجبة مناسبة، ثم راجعت طلبها قبل تأكيده. لاحظت أن التقنية تساعد على التنظيم لكنها لا تغني عن لطف التعامل مع العاملين. شكرت ليلى الموظف وساعدت أخاها الصغير على قراءة أسماء الأطعمة.","options":["داخل كتاب مدرسي","على شاشة","على باب الحافلة"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"remember"},"answer":{"correct":"على شاشة"}},{"lessonId":"854e3f92-2bbe-47c9-b790-abde711524c3","lessonTitle":"الدرس الحادي عشر: المطعم الذكي","page":10,"activity_order":206,"activity_type":"multiple_choice","title":"أتذكر المعلومة المناسبة","section":"practice","prompt":"ماذا فعلت ليلى قبل تأكيد طلبها؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"دخلت ليلى مطعمًا يستخدم شاشة لعرض قائمة الطعام. اختارت وجبة مناسبة، ثم راجعت طلبها قبل تأكيده. لاحظت أن التقنية تساعد على التنظيم لكنها لا تغني عن لطف التعامل مع العاملين. شكرت ليلى الموظف وساعدت أخاها الصغير على قراءة أسماء الأطعمة.","options":["تجاهلت الشاشة","راجعت الوجبة التي اختارتها","ألغت الطعام كله"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"understand"},"answer":{"correct":"راجعت الوجبة التي اختارتها"}},{"lessonId":"854e3f92-2bbe-47c9-b790-abde711524c3","lessonTitle":"الدرس الحادي عشر: المطعم الذكي","page":10,"activity_order":207,"activity_type":"multiple_choice","title":"أفسر القيمة أو النتيجة","section":"practice","prompt":"ما الفكرة التي فهمتها ليلى بشأن التقنية؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"دخلت ليلى مطعمًا يستخدم شاشة لعرض قائمة الطعام. اختارت وجبة مناسبة، ثم راجعت طلبها قبل تأكيده. لاحظت أن التقنية تساعد على التنظيم لكنها لا تغني عن لطف التعامل مع العاملين. شكرت ليلى الموظف وساعدت أخاها الصغير على قراءة أسماء الأطعمة.","options":["لا حاجة لمراجعة الطلبات","التقنية تنظم العمل ولا تغني عن التعامل اللطيف","التقنية تمنع الشكر والاحترام"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"apply"},"answer":{"correct":"التقنية تنظم العمل ولا تغني عن التعامل اللطيف"}},{"lessonId":"ead90a2e-97c0-42d7-a11b-c4162cda7f21","lessonTitle":"الدرس الخامس: نادر في المزرعة","page":7,"activity_order":205,"activity_type":"multiple_choice","title":"أفهم تفاصيل الحكاية","section":"practice","prompt":"مع من ذهب نادر إلى المزرعة؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"زار نادر مزرعة مع جده. شاهد أشجارًا وخضروات تنمو في أماكن مختلفة، ولاحظ عاملًا يسقي النباتات بقدر مناسب. قال له الجد: يحتاج النبات إلى الماء والضوء والعناية. ساعد نادر في جمع الأوراق المتساقطة في مكان مخصص لها، ثم سجل أسماء ثلاثة نباتات شاهدها.","options":["مع سائق حافلة","مع جده","مع زميله فقط"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"remember"},"answer":{"correct":"مع جده"}},{"lessonId":"ead90a2e-97c0-42d7-a11b-c4162cda7f21","lessonTitle":"الدرس الخامس: نادر في المزرعة","page":7,"activity_order":206,"activity_type":"multiple_choice","title":"أتذكر المعلومة المناسبة","section":"practice","prompt":"ما الذي يحتاج إليه النبات حسب نصيحة الجد؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"زار نادر مزرعة مع جده. شاهد أشجارًا وخضروات تنمو في أماكن مختلفة، ولاحظ عاملًا يسقي النباتات بقدر مناسب. قال له الجد: يحتاج النبات إلى الماء والضوء والعناية. ساعد نادر في جمع الأوراق المتساقطة في مكان مخصص لها، ثم سجل أسماء ثلاثة نباتات شاهدها.","options":["الصخور وحدها","الماء والضوء والعناية","الماء وحده دون ضوء"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"understand"},"answer":{"correct":"الماء والضوء والعناية"}},{"lessonId":"ead90a2e-97c0-42d7-a11b-c4162cda7f21","lessonTitle":"الدرس الخامس: نادر في المزرعة","page":7,"activity_order":207,"activity_type":"multiple_choice","title":"أفسر القيمة أو النتيجة","section":"practice","prompt":"ماذا فعل نادر بعد المساعدة في جمع الأوراق؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"زار نادر مزرعة مع جده. شاهد أشجارًا وخضروات تنمو في أماكن مختلفة، ولاحظ عاملًا يسقي النباتات بقدر مناسب. قال له الجد: يحتاج النبات إلى الماء والضوء والعناية. ساعد نادر في جمع الأوراق المتساقطة في مكان مخصص لها، ثم سجل أسماء ثلاثة نباتات شاهدها.","options":["قطع أغصان الأشجار","سجل أسماء ثلاثة نباتات","أغلق المزرعة"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"apply"},"answer":{"correct":"سجل أسماء ثلاثة نباتات"}},{"lessonId":"bb91b071-ed16-46b9-a4c3-144cd1fcabf8","lessonTitle":"الدرس الرابع: معالم من بلادي","page":7,"activity_order":205,"activity_type":"multiple_choice","title":"أفهم تفاصيل الحكاية","section":"practice","prompt":"أين ذهبت هند مع أسرتها؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"سارت هند مع أسرتها في جولة للتعرف إلى معالم البحرين. شاهدت مباني قديمة وطرقات حديثة، والتقطت صورًا للأماكن المسموح بتصويرها. كتبت في دفترها أن المعلم التراثي يذكرنا بالماضي، وأن المحافظة عليه مسؤولية الجميع. قررت هند أن تحكي لزميلاتها ما تعلمته.","options":["إلى غابة استوائية","في جولة لمعالم البحرين","إلى كوكب بعيد"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"remember"},"answer":{"correct":"في جولة لمعالم البحرين"}},{"lessonId":"bb91b071-ed16-46b9-a4c3-144cd1fcabf8","lessonTitle":"الدرس الرابع: معالم من بلادي","page":7,"activity_order":206,"activity_type":"multiple_choice","title":"أتذكر المعلومة المناسبة","section":"practice","prompt":"متى التقطت هند الصور خلال الجولة؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"سارت هند مع أسرتها في جولة للتعرف إلى معالم البحرين. شاهدت مباني قديمة وطرقات حديثة، والتقطت صورًا للأماكن المسموح بتصويرها. كتبت في دفترها أن المعلم التراثي يذكرنا بالماضي، وأن المحافظة عليه مسؤولية الجميع. قررت هند أن تحكي لزميلاتها ما تعلمته.","options":["دون احترام التعليمات","في الأماكن المسموح بتصويرها","في كل مكان ممنوع"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"understand"},"answer":{"correct":"في الأماكن المسموح بتصويرها"}},{"lessonId":"bb91b071-ed16-46b9-a4c3-144cd1fcabf8","lessonTitle":"الدرس الرابع: معالم من بلادي","page":7,"activity_order":207,"activity_type":"multiple_choice","title":"أفسر القيمة أو النتيجة","section":"practice","prompt":"لماذا نحافظ على المعالم التراثية؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"سارت هند مع أسرتها في جولة للتعرف إلى معالم البحرين. شاهدت مباني قديمة وطرقات حديثة، والتقطت صورًا للأماكن المسموح بتصويرها. كتبت في دفترها أن المعلم التراثي يذكرنا بالماضي، وأن المحافظة عليه مسؤولية الجميع. قررت هند أن تحكي لزميلاتها ما تعلمته.","options":["حتى نهدمها لاحقًا","لأنها تذكرنا بالماضي","لأنها غير مهمة"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"apply"},"answer":{"correct":"لأنها تذكرنا بالماضي"}},{"lessonId":"ec7bff48-8d51-4404-a1c6-ed1efa394290","lessonTitle":"الدرس السابع: جاسم والببغاء","page":8,"activity_order":205,"activity_type":"multiple_choice","title":"أفهم تفاصيل الحكاية","section":"practice","prompt":"أي طائر شاهد جاسم؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"شاهد جاسم ببغاءً ملونًا في مكان مخصص لرعاية الطيور. أحب ألوانه، وسأل المشرف عن طعامه المناسب. تعلم جاسم أن رعاية الحيوانات تحتاج إلى معرفة ومسؤولية، وأنه لا يجوز إزعاجها من أجل اللعب. عاد إلى المنزل ورسم الطائر وكتب قاعدة لطيفة عن الرفق بالحيوان.","options":["بطًّا في البركة","ببغاءً ملونًا","نسرًا فوق الجبل"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"remember"},"answer":{"correct":"ببغاءً ملونًا"}},{"lessonId":"ec7bff48-8d51-4404-a1c6-ed1efa394290","lessonTitle":"الدرس السابع: جاسم والببغاء","page":8,"activity_order":206,"activity_type":"multiple_choice","title":"أتذكر المعلومة المناسبة","section":"practice","prompt":"مَن سأله جاسم عن طعام الطائر المناسب؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"شاهد جاسم ببغاءً ملونًا في مكان مخصص لرعاية الطيور. أحب ألوانه، وسأل المشرف عن طعامه المناسب. تعلم جاسم أن رعاية الحيوانات تحتاج إلى معرفة ومسؤولية، وأنه لا يجوز إزعاجها من أجل اللعب. عاد إلى المنزل ورسم الطائر وكتب قاعدة لطيفة عن الرفق بالحيوان.","options":["معلم الحساب","المشرف على رعاية الطيور","سائق السيارة"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"understand"},"answer":{"correct":"المشرف على رعاية الطيور"}},{"lessonId":"ec7bff48-8d51-4404-a1c6-ed1efa394290","lessonTitle":"الدرس السابع: جاسم والببغاء","page":8,"activity_order":207,"activity_type":"multiple_choice","title":"أفسر القيمة أو النتيجة","section":"practice","prompt":"ما السلوك الذي تعلمه جاسم تجاه الطيور؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"شاهد جاسم ببغاءً ملونًا في مكان مخصص لرعاية الطيور. أحب ألوانه، وسأل المشرف عن طعامه المناسب. تعلم جاسم أن رعاية الحيوانات تحتاج إلى معرفة ومسؤولية، وأنه لا يجوز إزعاجها من أجل اللعب. عاد إلى المنزل ورسم الطائر وكتب قاعدة لطيفة عن الرفق بالحيوان.","options":["إطعامها أي شيء دون سؤال","الرفق بها وعدم إزعاجها","إزعاجها للتسلية"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"apply"},"answer":{"correct":"الرفق بها وعدم إزعاجها"}},{"lessonId":"0f5904ec-8aa7-46fa-894b-989c956bf8d9","lessonTitle":"الدرس السادس: النخلة","page":8,"activity_order":205,"activity_type":"multiple_choice","title":"أفهم تفاصيل الحكاية","section":"practice","prompt":"ماذا رأى حمد على النخلة؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"وقف حمد أمام نخلة في الحديقة، ورأى سعفها المرتفع وثمارها. سأل أمه عن أهمية النخلة، فأخبرته أنها من الأشجار المعروفة في بيئتنا وأن الناس يستفيدون من ثمارها. رسم حمد نخلة في دفتره، وكتب تحتها جملة: أحافظ على الأشجار ولا أكسر أغصانها.","options":["أزهارًا صناعية","سعفها المرتفع وثمارها","ألعابًا إلكترونية"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"remember"},"answer":{"correct":"سعفها المرتفع وثمارها"}},{"lessonId":"0f5904ec-8aa7-46fa-894b-989c956bf8d9","lessonTitle":"الدرس السادس: النخلة","page":8,"activity_order":206,"activity_type":"multiple_choice","title":"أتذكر المعلومة المناسبة","section":"practice","prompt":"من أخبر حمد بأهمية النخلة؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"وقف حمد أمام نخلة في الحديقة، ورأى سعفها المرتفع وثمارها. سأل أمه عن أهمية النخلة، فأخبرته أنها من الأشجار المعروفة في بيئتنا وأن الناس يستفيدون من ثمارها. رسم حمد نخلة في دفتره، وكتب تحتها جملة: أحافظ على الأشجار ولا أكسر أغصانها.","options":["عامل المتجر","أمه","صديقه عبر الهاتف"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"understand"},"answer":{"correct":"أمه"}},{"lessonId":"0f5904ec-8aa7-46fa-894b-989c956bf8d9","lessonTitle":"الدرس السادس: النخلة","page":8,"activity_order":207,"activity_type":"multiple_choice","title":"أفسر القيمة أو النتيجة","section":"practice","prompt":"ما العبارة التي كتبها حمد تحت رسم النخلة؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"وقف حمد أمام نخلة في الحديقة، ورأى سعفها المرتفع وثمارها. سأل أمه عن أهمية النخلة، فأخبرته أنها من الأشجار المعروفة في بيئتنا وأن الناس يستفيدون من ثمارها. رسم حمد نخلة في دفتره، وكتب تحتها جملة: أحافظ على الأشجار ولا أكسر أغصانها.","options":["أترك الشجرة بلا عناية","أحافظ على الأشجار ولا أكسر أغصانها","أكسر الأغصان لألعب"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"apply"},"answer":{"correct":"أحافظ على الأشجار ولا أكسر أغصانها"}},{"lessonId":"3b6a6f10-36b6-44b7-8617-40ea2b583107","lessonTitle":"الدرس العاشر: سفينة الفضاء","page":9,"activity_order":205,"activity_type":"multiple_choice","title":"أفهم تفاصيل الحكاية","section":"practice","prompt":"مم صنعت هبة نموذج سفينة الفضاء؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"صنعت هبة سفينة فضاء من علبة كرتونية نظيفة. أضافت نافذة دائرية وأجنحة من الورق، ثم تخيلت رحلة إلى كوكب بعيد. سألت أباها عن عمل رواد الفضاء، فشرح لها أنهم يتعلمون كثيرًا قبل السفر ويعملون في فريق. قررت هبة قراءة كتاب مصور عن استكشاف الفضاء.","options":["من الحديد الثقيل","من علبة كرتونية نظيفة","من الزجاج المكسور"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"remember"},"answer":{"correct":"من علبة كرتونية نظيفة"}},{"lessonId":"3b6a6f10-36b6-44b7-8617-40ea2b583107","lessonTitle":"الدرس العاشر: سفينة الفضاء","page":9,"activity_order":206,"activity_type":"multiple_choice","title":"أتذكر المعلومة المناسبة","section":"practice","prompt":"ماذا أضافت هبة إلى النموذج؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"صنعت هبة سفينة فضاء من علبة كرتونية نظيفة. أضافت نافذة دائرية وأجنحة من الورق، ثم تخيلت رحلة إلى كوكب بعيد. سألت أباها عن عمل رواد الفضاء، فشرح لها أنهم يتعلمون كثيرًا قبل السفر ويعملون في فريق. قررت هبة قراءة كتاب مصور عن استكشاف الفضاء.","options":["سياجًا للمزرعة","نافذة دائرية وأجنحة ورقية","عجلات شاحنة"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"understand"},"answer":{"correct":"نافذة دائرية وأجنحة ورقية"}},{"lessonId":"3b6a6f10-36b6-44b7-8617-40ea2b583107","lessonTitle":"الدرس العاشر: سفينة الفضاء","page":9,"activity_order":207,"activity_type":"multiple_choice","title":"أفسر القيمة أو النتيجة","section":"practice","prompt":"ماذا تعلمت هبة عن رواد الفضاء؟","content":{"origin":"DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030","originalText":"صنعت هبة سفينة فضاء من علبة كرتونية نظيفة. أضافت نافذة دائرية وأجنحة من الورق، ثم تخيلت رحلة إلى كوكب بعيد. سألت أباها عن عمل رواد الفضاء، فشرح لها أنهم يتعلمون كثيرًا قبل السفر ويعملون في فريق. قررت هبة قراءة كتاب مصور عن استكشاف الفضاء.","options":["يعمل كل رائد وحده دائمًا","يستعدون بالعلم ويعملون في فريق","يسافرون دون تدريب"],"sourceKind":"Original independent Bahrain Grade2 supporting story from lesson content, official Ministry second-term edition not certified","grade":2,"bloom":"apply"},"answer":{"correct":"يستعدون بالعلم ويعملون في فريق"}}]$g2story$::jsonb)
AS t("lessonId" text,"lessonTitle" text,page int,activity_order int,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $guard$
DECLARE eligible integer; inserted integer;
BEGIN
 IF (SELECT count(*) FROM pg_temp.bh_g2_12_original_stories_36)<>36
 OR (SELECT count(DISTINCT lesson_id) FROM pg_temp.bh_g2_12_original_stories_36)<>12
 OR (SELECT count(DISTINCT (lesson_id,activity_order)) FROM pg_temp.bh_g2_12_original_stories_36)<>36
 OR EXISTS(SELECT 1 FROM pg_temp.bh_g2_12_original_stories_36 t WHERE
  t.activity_order NOT BETWEEN 205 AND 207 OR t.activity_type<>'multiple_choice'
  OR length(t.prompt)<15 OR length(t.content->>'originalText')<155
  OR t.content ? 'answer' OR t.content ? 'correct'
  OR jsonb_array_length(t.content->'options')<>3
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(t.content->'options') o WHERE o=t.answer->>'correct'))
 THEN RAISE EXCEPTION 'Invalid source-specific Grade2 reading activities'; END IF;
 SELECT count(DISTINCT l.id) INTO eligible FROM public.lessons l
 JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.bh_g2_12_original_stories_36 t ON t.lesson_id=l.id AND t.lesson_title=l.title AND t.source_page=l.source_page_start
 WHERE l.status='published' AND co.code='BH' AND g.grade_number=2 AND l.source_pdf_url IS NOT NULL
 AND l.content LIKE '%نص قراءة أصلي داعم يقرأه المتعلم بمساعدة المعلم:%'
 AND position(t.content->>'originalText' IN l.content)>0
 AND (SELECT count(*) FROM public.lesson_activities a WHERE a.lesson_id=l.id AND a.is_published)=3
 AND (SELECT max(a.activity_order) FROM public.lesson_activities a WHERE a.lesson_id=l.id)=204
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts t JOIN public.lesson_activities a ON a.id=t.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts t JOIN public.questions q ON q.id=t.question_id WHERE q.lesson_id=l.id);
 IF eligible<>12 THEN RAISE EXCEPTION 'Content/lesson/history drift: % / 12',eligible; END IF;
 IF EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.content->>'origin'='DADYOOM_BH_G2_12_STORY_PASSAGES_36_SPECIFIC_MCQ_20261030')
 THEN RAISE EXCEPTION 'Refuse already-inserted 12 lesson batch'; END IF;
 INSERT INTO public.lesson_activities(lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT l.id,t.title,t.activity_type,'اقرأ نص ضاديوم الإثرائي ثم أجب. هذا دعم مستقل لا يثبت مطابقة نص الكتاب المدرسي.',
 t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.bh_g2_12_original_stories_36 t ON t.lesson_id=l.id AND t.lesson_title=l.title AND t.source_page=l.source_page_start
 WHERE l.status='published' AND co.code='BH' AND g.grade_number=2
 AND position(t.content->>'originalText' IN l.content)>0
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>36 THEN RAISE EXCEPTION 'Atomic rollback: only % / 36 source-exact Grade2 exercises',inserted; END IF;
END $guard$;
COMMIT;